const portraitName = "SvenPortrait";
const portraitFile = "worlds/ruiny/assets/portraits/svan.png";
const position = { x: 300, y: 700 };
const scale = 0.6;
const fadeTime = 500;

if (Sequencer.EffectManager.getEffects({ name: portraitName }).length > 0) {
  Sequencer.EffectManager.endEffects({ name: portraitName });
  ui.notifications.info("Портрет скрыт.");
} else {
  new Sequence()
    .effect()
    .file(portraitFile)
    .atLocation(position)
    .scale(scale)
    .name(portraitName)
    .fadeIn(fadeTime)
    .persist()
    .fadeOut(fadeTime)
    .play();
  ui.notifications.info("Портрет показан.");
}
